module.exports = [
// ---- Pretreatment: desizing, scouring, bleaching, mercerizing ----
{ q: "A fabric sample tests positive with iodine solution (turns blue-black) after weaving but before any wet processing. What does this indicate?", options: ["The fabric contains residual starch size on the warp yarns", "The fabric has been over-bleached", "The dye used is a vat dye", "The fabric has poor colorfastness"], correct: "The fabric contains residual starch size on the warp yarns", exp: "Iodine forms a blue-black complex specifically with starch; a positive test after weaving (before desizing) confirms starch-based sizing agent is still present and must be removed by desizing.", difficulty: "intermediate", tags: ["pretreatment","desizing"] },
{ q: "Enzymatic desizing is preferred over acid or oxidative desizing mainly because it:", options: ["Is faster than all other methods regardless of fabric type", "Selectively hydrolyzes starch without attacking the cellulose fiber", "Bleaches the fabric simultaneously", "Requires no water"], correct: "Selectively hydrolyzes starch without attacking the cellulose fiber", exp: "Amylase enzymes specifically break down starch (size) molecules into soluble sugars, leaving the cellulose fiber structure undamaged, unlike acid desizing which can cause tendering.", difficulty: "intermediate", tags: ["desizing","enzyme"] },
{ q: "During scouring, the primary chemical(s) used to remove natural wax, oils, and impurities from cotton are:", options: ["Sodium hypochlorite and water", "Caustic soda (NaOH) with a wetting agent, under heat", "Hydrogen peroxide alone at room temperature", "Sulfuric acid"], correct: "Caustic soda (NaOH) with a wetting agent, under heat", exp: "Scouring uses hot alkali (NaOH) plus surfactants to saponify waxes and emulsify natural oils/impurities, making the fiber hydrophilic before dyeing.", difficulty: "basic", tags: ["scouring"] },
{ q: "A mill switches from separate desizing-scouring-bleaching steps to a combined 'kier boiling' style single-bath process. The main tradeoff is:", options: ["Better whiteness but higher water use", "Time and cost savings, but less precise control over each individual step's chemistry", "It only works on synthetic fibers", "It eliminates the need for bleaching entirely"], correct: "Time and cost savings, but less precise control over each individual step's chemistry", exp: "Combined processing saves energy, water, and time, but because all reactions happen simultaneously in one bath, individual process parameters (like desizing enzyme temperature vs bleach concentration) can't be independently optimized.", difficulty: "advanced", tags: ["pretreatment"] },
{ q: "Why is hydrogen peroxide bleaching generally preferred over sodium hypochlorite bleaching for cotton going into pastel/light dyeing?", options: ["Peroxide is cheaper", "Peroxide gives a more stable, non-yellowing whiteness and avoids chlorine-related fiber damage", "Hypochlorite cannot remove any color at all", "Peroxide requires no stabilizer"], correct: "Peroxide gives a more stable, non-yellowing whiteness and avoids chlorine-related fiber damage", exp: "Hypochlorite bleaching risks chlorine retention, fiber tendering, and 'phototendering'/yellowing over time, whereas hydrogen peroxide (properly stabilized with silicate/stabilizer) gives durable, chlorine-free whiteness.", difficulty: "intermediate", tags: ["bleaching"] },
{ q: "In hydrogen peroxide bleaching, a silicate or organic stabilizer is added mainly to:", options: ["Add fragrance to the bath", "Control the decomposition rate of peroxide and prevent catalytic (metal-ion) damage to the fiber", "Increase the fabric's final GSM", "Neutralize the caustic soda completely"], correct: "Control the decomposition rate of peroxide and prevent catalytic (metal-ion) damage to the fiber", exp: "Without a stabilizer, trace metal ions (iron, copper) catalyze uncontrolled peroxide decomposition, generating localized radicals that cause pinholes and fiber tendering.", difficulty: "advanced", tags: ["bleaching"] },
{ q: "Mercerization of cotton under tension with concentrated caustic soda primarily improves:", options: ["Only the fabric's flame resistance", "Luster, dye uptake/affinity, tensile strength, and dimensional stability", "Only the fabric's softness, with no effect on dyeing", "The fabric's resistance to pilling only"], correct: "Luster, dye uptake/affinity, tensile strength, and dimensional stability", exp: "Mercerization swells the cotton fiber, converting it to a rounder cross-section, which increases luster, improves dye site accessibility (higher color yield), and increases strength when done under tension.", difficulty: "basic", tags: ["mercerization"] },
{ q: "If mercerization is done WITHOUT tension (slack mercerization), what is the main consequence compared to tensioned mercerization?", options: ["Identical results in every respect", "Fabric shrinks and gains stretch/elastic recovery, but loses some of the luster gain seen with tension", "The fabric becomes permanently stiff", "Dye uptake decreases drastically"], correct: "Fabric shrinks and gains stretch/elastic recovery, but loses some of the luster gain seen with tension", exp: "Slack mercerization is used specifically when stretch/recovery properties (e.g., for knits) are wanted; without tension holding the swollen fiber's round shape, the luster boost is reduced relative to tension mercerizing.", difficulty: "advanced", tags: ["mercerization"] },
{ q: "A dyer notices uneven, patchy dyeing on a batch even though pretreatment looked visually uniform. The most likely root cause to check first is:", options: ["The dye lot number printed on the package", "Uneven residual alkalinity or incomplete/uneven scouring across the fabric width, causing differential absorbency", "The color of the dyeing machine", "The brand of the yarn cone"], correct: "Uneven residual alkalinity or incomplete/uneven scouring across the fabric width, causing differential absorbency", exp: "Dye uptake is extremely sensitive to fiber absorbency/wettability; uneven scouring leaves patches with different residual wax/impurity levels, which absorb dye at different rates even if the fabric looks visually 'clean.'", difficulty: "advanced", tags: ["dyeing-faults"] },
{ q: "The purpose of a 'singeing' step, typically done before desizing, is to:", options: ["Add color to the fabric surface", "Burn off protruding fiber ends (fuzz) from the fabric surface using a gas flame for a cleaner surface", "Increase the fabric weight", "Replace the bleaching step entirely"], correct: "Burn off protruding fiber ends (fuzz) from the fabric surface using a gas flame for a cleaner surface", exp: "Singeing passes fabric rapidly over an open flame to burn off surface fuzz/protruding fibers, giving a smoother surface especially important before printing or for smooth-finish fabrics.", difficulty: "basic", tags: ["pretreatment","singeing"] },

// ---- Dyeing chemistry & classes ----
{ q: "Reactive dyes are the dominant dye class for cotton mainly because they:", options: ["Only work at room temperature with no chemicals", "Form a true covalent bond with the cellulose hydroxyl groups, giving excellent wash fastness", "Are always cheaper than direct dyes", "Never require a fixation/wash-off step"], correct: "Form a true covalent bond with the cellulose hydroxyl groups, giving excellent wash fastness", exp: "Reactive dyes chemically bond (covalent bond) to the -OH groups of cellulose, unlike direct dyes which rely on weaker Van der Waals/hydrogen bonding — hence reactive dyes give superior wash fastness on cotton.", difficulty: "basic", tags: ["reactive-dye"] },
{ q: "In reactive dyeing, a large amount of salt (NaCl or Na2SO4) is added to the dye bath primarily to:", options: ["Whiten the fabric", "Suppress the dye's solubility repulsion and push (exhaust) the anionic dye onto the negatively-charged cellulose fiber", "Neutralize the fixation alkali", "Act as the fixing agent itself, replacing soda ash"], correct: "Suppress the dye's solubility repulsion and push (exhaust) the anionic dye onto the negatively-charged cellulose fiber", exp: "Both the reactive dye and cellulose fiber carry negative charges in water, which repel the dye away from the fiber. Salt shields this charge repulsion (Le Chatelier/ionic strength effect), driving dye exhaustion onto the fiber, before alkali is added separately for fixation.", difficulty: "advanced", tags: ["reactive-dye","exhaustion"] },
{ q: "Why can't reactive dyes normally be used to dye 100% polyester?", options: ["Polyester has no reactive sites and reactive dyes need a hydrophilic fiber with reactive hydroxyl/amine groups to bond with", "Polyester melts at dyeing temperature", "Reactive dyes are too expensive for synthetic fiber", "Polyester already has a dark natural color"], correct: "Polyester has no reactive sites and reactive dyes need a hydrophilic fiber with reactive hydroxyl/amine groups to bond with", exp: "Polyester is a hydrophobic, chemically inert fiber with no accessible -OH/-NH groups for covalent bonding, and its compact structure blocks large water-soluble reactive dye molecules — disperse dyes are used instead.", difficulty: "intermediate", tags: ["reactive-dye","polyester"] },
{ q: "Disperse dyes, used for polyester, are unique among dye classes because they:", options: ["Are ionic and dissolve completely in water like reactive dyes", "Are essentially water-insoluble and dye the fiber via a fine aqueous dispersion that diffuses into the hydrophobic polymer", "Require no heat at all to dye polyester", "Bond covalently with polyester like reactive dyes bond with cotton"], correct: "Are essentially water-insoluble and dye the fiber via a fine aqueous dispersion that diffuses into the hydrophobic polymer", exp: "Disperse dyes have very low water solubility; they are applied as a fine particle dispersion, and at high temperature (or with a carrier), individual dye molecules diffuse into and dissolve within the hydrophobic polyester polymer matrix.", difficulty: "intermediate", tags: ["disperse-dye"] },
{ q: "Standard polyester dyeing with disperse dyes at atmospheric pressure (100°C, no HTHP machine or carrier) usually gives poor exhaustion because:", options: ["Polyester fiber is chemically incompatible with all disperse dyes", "Below the polyester glass transition temperature, the polymer chains are too tightly packed for dye molecules to diffuse in effectively", "Disperse dyes are always too large a molecule regardless of temperature", "The dye bath pH is always wrong"], correct: "Below the polyester glass transition temperature, the polymer chains are too tightly packed for dye molecules to diffuse in effectively", exp: "Polyester needs to be dyed above ~100°C (typically 130°C under HTHP) or with a carrier chemical to sufficiently 'open up' (soften) the tightly packed polymer chains so dye molecules can diffuse inside.", difficulty: "advanced", tags: ["disperse-dye","HTHP"] },
{ q: "Vat dyes (e.g., indigo) are insoluble in water in their original form. To dye with them, they must first be:", options: ["Heated above their melting point", "Chemically reduced (using a reducing agent like sodium hydrosulfite) into a soluble 'leuco' form, then reoxidized on the fiber after application", "Ground into a fine powder and applied dry", "Mixed with acid to dissolve directly"], correct: "Chemically reduced (using a reducing agent like sodium hydrosulfite) into a soluble 'leuco' form, then reoxidized on the fiber after application", exp: "Vat dyeing works via reduction (vatting) to convert the insoluble pigment to a soluble leuco-form that penetrates the fiber, then oxidation (exposure to air or an oxidizing agent) reconverts it back to the original insoluble, wash-fast pigment inside the fiber.", difficulty: "intermediate", tags: ["vat-dye"] },
{ q: "Denim's characteristic surface-only (ring) dyeing with indigo, which allows abrasion/wash effects to create fading patterns, happens because:", options: ["Indigo permanently dyes all the way through the yarn cross-section", "Indigo has poor penetration and low affinity, staying mostly on the fiber surface of the yarn rather than penetrating the core", "The yarn is dyed with reactive dye, not indigo", "Denim yarn has no core at all"], correct: "Indigo has poor penetration and low affinity, staying mostly on the fiber surface of the yarn rather than penetrating the core", exp: "Indigo's ring-dyeing effect (surface-concentrated color, white/undyed core) is precisely why abrasion during washing or sandblasting can create the classic faded denim look — a fully penetrated dye would not fade this way.", difficulty: "advanced", tags: ["vat-dye","denim"] },
{ q: "Acid dyes are the standard choice for dyeing wool and silk mainly because these fibers:", options: ["Are cellulose-based like cotton", "Are protein fibers with amine (-NH2) groups that form ionic bonds with the anionic acid dye under acidic pH", "Cannot be dyed with any other class", "Require no dye bath pH control"], correct: "Are protein fibers with amine (-NH2) groups that form ionic bonds with the anionic acid dye under acidic pH", exp: "Under acidic conditions, protein fiber amine groups become protonated (positively charged) and form ionic attractions with the negatively charged acid dye anions, giving good uptake and fastness on wool/silk/nylon.", difficulty: "intermediate", tags: ["acid-dye"] },
{ q: "Sulphur dyes are widely used for dyeing cotton in dark shades like black and navy mainly because they offer:", options: ["The brightest possible shades at the lowest cost per kg of dye", "Very good wash and light fastness at low cost, though with generally duller shades than reactive dyes", "Perfect shade brightness with no environmental concerns", "Compatibility only with wool"], correct: "Very good wash and light fastness at low cost, though with generally duller shades than reactive dyes", exp: "Sulphur dyes are economical and give excellent fastness for deep/dark shades (especially black), which is why they dominate that segment, but they trade off some brightness/vibrancy compared to reactive dyes.", difficulty: "intermediate", tags: ["sulphur-dye"] },
{ q: "A dye house needs to dye a poly-cotton blend (65/35) to a solid, matching shade on both fibers in one recipe. The technically correct approach is:", options: ["Use only reactive dye — it will dye both fibers equally", "Use a combination of disperse dye (for the polyester) and reactive dye (for the cotton) in a two-stage process", "Use only acid dye for both fibers", "Blended fibers cannot be dyed a solid shade at all"], correct: "Use a combination of disperse dye (for the polyester) and reactive dye (for the cotton) in a two-stage process", exp: "Since disperse dye has no affinity for cotton and reactive dye has no affinity for polyester, poly-cotton blends require both dye classes applied in sequence (often disperse first at high temp, then reactive) to achieve a solid, level shade across the blend.", difficulty: "advanced", tags: ["blend-dyeing"] },
{ q: "Azoic (naphthol) dyeing is distinct from other dye classes because the color is actually:", options: ["Pre-formed like any normal dye and simply applied", "Synthesized directly INSIDE the fiber by combining a naphthol (coupling component) with a diazonium salt (base) in sequence", "Applied only as a pigment print paste", "Impossible to achieve bright reds and oranges"], correct: "Synthesized directly INSIDE the fiber by combining a naphthol (coupling component) with a diazonium salt (base) in sequence", exp: "Azoic dyeing is unique: the fiber is first impregnated with the naphtholate, then treated with a diazonium salt — the azo dye color forms via a coupling reaction that happens inside the fiber itself, giving very bright, fast reds/oranges.", difficulty: "advanced", tags: ["azoic-dye"] },
{ q: "Basic (cationic) dyes give extremely bright, vivid shades but are mainly limited to acrylic fiber because:", options: ["They are too expensive for any other fiber", "Acrylic fiber contains anionic dye sites that strongly bond with the cationic dye; other common fibers lack this and show poor fastness with basic dyes", "Basic dyes cannot dissolve in water", "Cotton has too many dye sites for basic dyes to work"], correct: "Acrylic fiber contains anionic dye sites that strongly bond with the cationic dye; other common fibers lack this and show poor fastness with basic dyes", exp: "Acrylic is engineered with anionic (negatively charged) co-monomer sites specifically to ionically bond with cationic basic dyes, giving brilliant color and good fastness — on cotton or polyester, basic dyes bond poorly and fade/bleed badly.", difficulty: "advanced", tags: ["basic-dye","acrylic"] },
{ q: "Direct dyes are sometimes called 'substantive' dyes for cellulose. What is their main practical drawback compared to reactive dyes?", options: ["They cannot dye cotton at all", "They rely on weaker physical (hydrogen bond/Van der Waals) attraction rather than a covalent bond, so wet/wash fastness is generally lower", "They are far more expensive than reactive dyes", "They require a diazonium salt to work"], correct: "They rely on weaker physical (hydrogen bond/Van der Waals) attraction rather than a covalent bond, so wet/wash fastness is generally lower", exp: "Direct dyes' 'substantivity' for cellulose comes from physical attraction forces, not a chemical bond — this makes them simple/cheap to apply but generally gives inferior wet fastness compared to reactive dyes, often requiring a fixing agent afterward.", difficulty: "intermediate", tags: ["direct-dye"] },
{ q: "A shade recipe calls for 'levelling agent' in the dyebath. Its function is to:", options: ["Speed up the initial rate of dye exhaustion as much as possible", "Control/slow the rate of dye uptake so the dye distributes evenly across the fabric instead of striking unevenly", "Permanently fix the dye to the fiber", "Replace the need for salt in reactive dyeing"], correct: "Control/slow the rate of dye uptake so the dye distributes evenly across the fabric instead of striking unevenly", exp: "Levelling agents temporarily compete with the fiber for dye or slow dye migration/diffusion, preventing fast 'strike' that would cause dark patches and uneven, unlevel dyeing.", difficulty: "intermediate", tags: ["levelling-agent"] },
{ q: "'Dye exhaustion' refers to:", options: ["The point at which the dye machine runs out of power", "The percentage of dye that transfers from the dyebath liquor onto the fiber", "The fading of a dye under sunlight over time", "The temperature at which a dye decomposes"], correct: "The percentage of dye that transfers from the dyebath liquor onto the fiber", exp: "Exhaustion (%) measures how much of the total dye added to the bath actually ends up fixed on/in the fiber versus remaining in the residual liquor — higher exhaustion means less dye wasted in effluent.", difficulty: "basic", tags: ["exhaustion"] },
{ q: "A reactive-dyed batch shows excellent depth of shade but poor wash fastness (color bleeds badly in the first wash). The most likely process failure is:", options: ["Too much salt was used", "Incomplete fixation (alkali/soda ash step) and/or inadequate soaping-off of unfixed hydrolyzed dye", "The fabric was scoured too well", "The dye was a vat dye instead of reactive"], correct: "Incomplete fixation (alkali/soda ash step) and/or inadequate soaping-off of unfixed hydrolyzed dye", exp: "If fixation alkali dosing/time/temperature is insufficient, much of the exhausted dye never covalently bonds and remains loosely held (or hydrolyzed); without a thorough hot soaping/wash-off step to remove this unfixed dye, it bleeds out in the customer's first wash.", difficulty: "advanced", tags: ["reactive-dye","fastness"] },

// ---- Dyeing machinery & methods ----
{ q: "Jigger dyeing machines move the fabric (in open-width, rope-free form) back and forth between two rollers through a stationary dye bath. This method is best suited for:", options: ["Loose fiber stock only", "Woven fabrics that are sensitive to crease/rope marks and need open-width handling", "Only knit fabrics in rope form", "Garments after stitching"], correct: "Woven fabrics that are sensitive to crease/rope marks and need open-width handling", exp: "Because the fabric stays open-width and under controlled tension on a jigger, it avoids the crease marks that rope-form machines (like winch/jet) can cause on crease-prone woven fabrics.", difficulty: "intermediate", tags: ["jigger"] },
{ q: "Winch (beck) dyeing machines process fabric in rope form. A key limitation of rope-form dyeing is:", options: ["It cannot dye any synthetic fiber", "It can cause permanent crease marks on fabrics prone to creasing, like some synthetics or heavy fabrics", "It uses far more dye chemical than any other method", "It only works for garment dyeing"], correct: "It can cause permanent crease marks on fabrics prone to creasing, like some synthetics or heavy fabrics", exp: "In rope form, fabric is folded/bunched as it circulates, and crease-sensitive fabrics (e.g., certain synthetics, heavier wovens) can develop permanent crease lines from this repeated folding under heat and tension.", difficulty: "intermediate", tags: ["winch"] },
{ q: "Jet dyeing machines circulate fabric rope using a high-velocity liquor jet instead of a mechanical reel. Their main advantage for synthetic fabrics is:", options: ["They operate only at low temperature", "They allow high-temperature/high-pressure (HTHP) dyeing of polyester with gentle fabric handling, minimizing mechanical stress and crease marks", "They eliminate the need for any dye chemicals", "They can only be used for cotton"], correct: "They allow high-temperature/high-pressure (HTHP) dyeing of polyester with gentle fabric handling, minimizing mechanical stress and crease marks", exp: "Jet dyeing machines are sealed, pressurized vessels that can reach the 130°C+ needed for efficient polyester (disperse) dyeing, while the liquor-jet propulsion handles the fabric more gently than mechanical reels.", difficulty: "advanced", tags: ["jet-dyeing"] },
{ q: "Package dyeing is a method where dye liquor is force-circulated through:", options: ["Loose fabric hanging freely in an open vat", "Yarn wound onto perforated spring tubes/cones (a 'package'), with liquor pumped in-to-out and out-to-in", "Finished garments only", "Fiber tow in continuous rope form on a range"], correct: "Yarn wound onto perforated spring tubes/cones (a 'package'), with liquor pumped in-to-out and out-to-in", exp: "Package dyeing is specifically for yarn (cones/cheeses) — liquor is pumped through the porous package under pressure, alternating flow direction to ensure even penetration and level dyeing throughout the yarn package.", difficulty: "basic", tags: ["package-dyeing"] },
{ q: "Continuous pad-steam dyeing (used for high-volume cotton reactive dyeing) differs fundamentally from batch/exhaust dyeing because:", options: ["It uses no water at all", "Fabric is impregnated (padded) with dye liquor to a controlled wet pick-up, then fixed by steaming, rather than dye being gradually exhausted from a large liquor bath over time", "It can only produce white fabric", "It requires no chemicals whatsoever"], correct: "Fabric is impregnated (padded) with dye liquor to a controlled wet pick-up, then fixed by steaming, rather than dye being gradually exhausted from a large liquor bath over time", exp: "Pad-steam applies a precisely controlled amount of dye directly onto the fabric via padding (squeeze rollers), then uses steam to rapidly fix it — this is far faster and more water/liquor-efficient than exhaust dyeing for long fabric runs, though shade reproducibility requires tight pick-up control.", difficulty: "advanced", tags: ["pad-steam","continuous-dyeing"] },
{ q: "'Liquor ratio' (L:R) in batch dyeing refers to:", options: ["The ratio of dye powder to water only", "The ratio of the total weight of dye liquor (water+chemicals) to the weight of the fabric/yarn being dyed", "The speed ratio of the machine's rollers", "The ratio of acid to alkali in the bath"], correct: "The ratio of the total weight of dye liquor (water+chemicals) to the weight of the fabric/yarn being dyed", exp: "L:R (e.g., 10:1) means 10 kg of liquor per 1 kg of material; a lower liquor ratio saves water, energy, and chemicals but requires machines capable of handling material at lower liquid volumes without abrasion damage.", difficulty: "basic", tags: ["liquor-ratio"] },
{ q: "Reducing the liquor ratio (e.g., from 10:1 to 5:1) in a modern low-liquor-ratio dyeing machine mainly benefits the mill by:", options: ["Increasing water, energy, and chemical (salt/dye) consumption", "Reducing water, energy, and chemical consumption per kg of fabric, since less liquor volume needs heating and dosing", "Making the shade always darker regardless of dye dosage", "Eliminating the need for any auxiliary chemicals"], correct: "Reducing water, energy, and chemical consumption per kg of fabric, since less liquor volume needs heating and dosing", exp: "Lower liquor ratio means less total water to heat and less total salt/chemical needed to achieve the same effective concentration, directly cutting utility and chemical costs and effluent volume.", difficulty: "intermediate", tags: ["liquor-ratio","sustainability"] },
{ q: "A garment-dyeing (dyeing after full garment construction, e.g., for a washed/vintage look) approach is generally NOT chosen when:", options: ["The brand wants a uniquely faded, worn-in aesthetic on a single style", "Extremely precise, batch-to-batch color matching across huge volumes with zero shade variation is required, since garment dyeing has more shade variability", "Small batch, quick-turnaround fashion orders are needed", "The style has heavy stitching/trims that benefit from a soft, aged look"], correct: "Extremely precise, batch-to-batch color matching across huge volumes with zero shade variation is required, since garment dyeing has more shade variability", exp: "Garment dyeing (piece dyeing after cut-and-sew) is prized for fast, flexible, unique finishes but is inherently harder to control for shade consistency at scale compared to dyeing fabric/yarn before construction.", difficulty: "advanced", tags: ["garment-dyeing"] },

// ---- Printing ----
{ q: "Rotary screen printing differs from flat-bed screen printing mainly in that it:", options: ["Cannot print more than one color", "Uses cylindrical, continuously rotating perforated screens, allowing continuous high-speed production instead of stop-start flat screens", "Is only used for pigment prints", "Produces lower resolution than any digital method"], correct: "Uses cylindrical, continuously rotating perforated screens, allowing continuous high-speed production instead of stop-start flat screens", exp: "Rotary screens rotate continuously as fabric moves beneath them, enabling much higher production speeds than flat-bed printing, which must stop/reposition the screen for each repeat.", difficulty: "intermediate", tags: ["rotary-printing"] },
{ q: "Digital textile printing (inkjet) is gaining share over conventional rotary screen printing mainly because it:", options: ["Is always cheaper at any order quantity, including very large runs", "Eliminates the need for engraved screens, enabling cost-effective small runs, fast design changes, and unlimited color/gradient complexity", "Cannot print on cotton", "Only works with vat dyes"], correct: "Eliminates the need for engraved screens, enabling cost-effective small runs, fast design changes, and unlimited color/gradient complexity", exp: "Screen printing requires a separate engraved screen per color (high setup cost, best for large runs); digital printing needs no screens, making it ideal for small batches, sampling, and complex multi-tonal designs, though at higher per-meter ink cost for large volumes.", difficulty: "intermediate", tags: ["digital-printing"] },
{ q: "'Discharge printing' works by:", options: ["Adding extra dye on top of an already-dyed ground color", "Printing a chemical paste that locally destroys/bleaches the pre-dyed ground color, sometimes replacing it with a new color simultaneously", "Printing only white pigment", "A method exclusive to polyester fabric"], correct: "Printing a chemical paste that locally destroys/bleaches the pre-dyed ground color, sometimes replacing it with a new color simultaneously", exp: "Discharge printing starts with a solid-dyed ground fabric, then prints a discharging agent that chemically destroys the dye in the printed areas — a 'color-discharge' paste can also deposit a new, discharge-resistant color at the same time.", difficulty: "advanced", tags: ["discharge-printing"] },
{ q: "'Resist printing' (e.g., batik-style) works on the opposite principle of discharge printing, in that it:", options: ["Removes color after dyeing", "Applies a wax, chemical, or mechanical barrier BEFORE dyeing so that area resists/rejects the dye and stays undyed or a different color", "Only works with pigment inks", "Is identical to rotary screen printing"], correct: "Applies a wax, chemical, or mechanical barrier BEFORE dyeing so that area resists/rejects the dye and stays undyed or a different color", exp: "Resist printing/dyeing applies a resist agent (wax, paste, or physical binding as in tie-dye) prior to dyeing, preventing dye penetration in those areas — the opposite sequence of discharge printing, which acts after dyeing.", difficulty: "advanced", tags: ["resist-printing"] },
{ q: "Pigment printing is extremely widely used in fashion printing despite pigments having no chemical affinity for any fiber. This works because:", options: ["Pigments dissolve into the fiber like a dye", "A binder resin in the print paste glues/encapsulates the pigment particles onto the fabric surface after curing", "The fabric is always pre-treated with acid first", "Pigments only work on wool"], correct: "A binder resin in the print paste glues/encapsulates the pigment particles onto the fabric surface after curing", exp: "Since pigments (unlike dyes) have no fiber affinity or solubility, a polymer binder is essential — after printing, curing (heat) cross-links the binder resin to mechanically hold pigment particles on the fabric surface.", difficulty: "intermediate", tags: ["pigment-printing"] },
{ q: "A pigment-printed garment feels noticeably stiffer/harder-handed than a reactive-printed one with the same design. The most likely reason is:", options: ["Pigment ink is naturally softer than reactive dye", "Excess binder resin was used, or curing was insufficient/excessive, affecting the hand-feel of the printed area", "The fabric was never washed", "Reactive printing always uses more chemical"], correct: "Excess binder resin was used, or curing was insufficient/excessive, affecting the hand-feel of the printed area", exp: "Because pigment printing relies entirely on a surface binder film (unlike reactive dye, which penetrates and bonds within the fiber), binder dosage and cure conditions directly control the stiffness/hand-feel of the printed area.", difficulty: "advanced", tags: ["pigment-printing","hand-feel"] },
{ q: "In roller printing (an older, largely superseded technique), color is applied via:", options: ["A flat stencil pressed by hand", "Engraved copper rollers, one per color, rotating in continuous contact with the fabric", "A digital printhead spraying ink droplets", "Wax-resist application by hand"], correct: "Engraved copper rollers, one per color, rotating in continuous contact with the fabric", exp: "Roller printing engraves the design into copper rollers (one roller per color) that pick up paste from a color trough and transfer it directly onto the moving fabric — high speed but with very high engraving setup cost, largely replaced by rotary screen and digital.", difficulty: "basic", tags: ["roller-printing"] },
{ q: "'Registration' problems in multi-color printing refer to:", options: ["Missing paperwork for the print order", "Misalignment between the different color separations/screens, causing blurred or offset design edges", "Incorrect fabric GSM", "Wrong dye recipe concentration"], correct: "Misalignment between the different color separations/screens, causing blurred or offset design edges", exp: "Each color in a multi-color print is applied by a separate screen/roller in sequence; if these aren't perfectly aligned (registered) to each other, the design shows visible color fringing/offset, a classic printing quality defect.", difficulty: "intermediate", tags: ["printing-defects"] },
{ q: "Burn-out (devoré) printing on a poly-cotton blend fabric works by printing a chemical (typically an acid-based paste) that:", options: ["Dyes only the polyester fiber", "Selectively dissolves/destroys the cellulose (cotton) fiber in the printed areas while leaving the polyester intact, creating a sheer, textured pattern", "Adds extra cotton fiber to the printed area", "Bleaches both fibers equally"], correct: "Selectively dissolves/destroys the cellulose (cotton) fiber in the printed areas while leaving the polyester intact, creating a sheer, textured pattern", exp: "Burn-out/devoré printing exploits the differing chemical resistance of the two fibers in a blend — an acid paste destroys the acid-sensitive cellulose, leaving the acid-resistant polyester intact as a sheer, patterned area.", difficulty: "advanced", tags: ["burnout-printing"] },
{ q: "Print paste thickener (e.g., sodium alginate for reactive printing) is essential mainly to:", options: ["Increase the color depth chemically", "Control paste viscosity so the design stays sharp and doesn't bleed/spread on the fabric before fixation", "Replace the need for a fixing/steaming step", "Act as the primary coloring agent"], correct: "Control paste viscosity so the design stays sharp and doesn't bleed/spread on the fabric before fixation", exp: "Thickener gives the print paste enough viscosity to hold a sharp printed pattern on the fabric surface (preventing capillary bleeding/spreading) until the fixation (steaming/curing) step locks the color in place.", difficulty: "intermediate", tags: ["print-paste"] },

// ---- Mechanical finishing ----
{ q: "Calendering passes fabric through heated rollers under pressure mainly to:", options: ["Add permanent color", "Flatten/smooth the fabric surface and impart luster or special surface effects (e.g., moire)", "Remove all shrinkage potential", "Increase fabric GSM permanently"], correct: "Flatten/smooth the fabric surface and impart luster or special surface effects (e.g., moire)", exp: "Calendering is a purely mechanical finish using heat and pressure between rollers to compress/smooth the fabric surface, which can increase luster/sheen and, with engraved rollers, create surface patterns like moire.", difficulty: "basic", tags: ["calendering"] },
{ q: "Sanforization (compressive shrinkage) is applied to woven cotton fabric primarily to:", options: ["Add a permanent print design", "Pre-shrink the fabric mechanically so the garment made from it doesn't shrink excessively during the customer's future washing", "Bleach the fabric white", "Dye the fabric a new color"], correct: "Pre-shrink the fabric mechanically so the garment made from it doesn't shrink excessively during the customer's future washing", exp: "Sanforizing mechanically compresses the fabric (compensating for the relaxation shrinkage that would otherwise happen in the first wash), so finished garments hold their stated size much better after laundering.", difficulty: "basic", tags: ["sanforizing"] },
{ q: "A woven cotton fabric is labeled 'sanforized' but still shrinks 6% after the first wash (spec allows max 3%). The most likely explanation is:", options: ["Sanforizing is completely ineffective and unrelated to shrinkage", "The compressive shrinkage percentage applied during finishing was insufficient for that fabric's actual relaxation shrinkage potential", "The fabric was over-dyed", "The GSM was too low"], correct: "The compressive shrinkage percentage applied during finishing was insufficient for that fabric's actual relaxation shrinkage potential", exp: "Sanforizing reduces shrinkage by a controlled, settable percentage; if the machine's compression setting wasn't matched to the fabric's actual shrinkage potential (which varies by construction/yarn), residual shrinkage can still exceed spec.", difficulty: "advanced", tags: ["sanforizing","shrinkage"] },
{ q: "Raising (napping) finish, used to create fabrics like flannel, works by:", options: ["Chemically dissolving the fabric surface", "Mechanically pulling/teasing individual fiber ends out of the yarn structure using wire rollers, creating a soft, fuzzy surface", "Printing a fuzzy pattern with pigment", "Adding extra weft yarns after weaving"], correct: "Mechanically pulling/teasing individual fiber ends out of the yarn structure using wire rollers, creating a soft, fuzzy surface", exp: "Raising uses rotating rollers covered in fine wire hooks/teasels that physically pull loose fiber ends up out of the yarn twist, forming the characteristic soft, fuzzy pile seen on flannel and fleece-type fabrics.", difficulty: "intermediate", tags: ["raising","napping"] },
{ q: "Shearing, typically done after raising, is used to:", options: ["Add more fiber to the surface", "Trim the raised/napped fiber pile to a uniform, even height for a consistent surface finish", "Apply the final dye color", "Measure the fabric's exact width"], correct: "Trim the raised/napped fiber pile to a uniform, even height for a consistent surface finish", exp: "After raising creates a fuzzy pile, shearing (like a mechanical trim/mow) cuts it to an even, controlled height, giving a clean, uniform surface appearance rather than an uneven, shaggy one.", difficulty: "basic", tags: ["shearing"] },
{ q: "Heat-setting of synthetic fabrics (e.g., polyester) at a controlled temperature/time is critical because it:", options: ["Has no permanent effect and is purely cosmetic", "Locks in the fabric's dimensional stability and reduces future shrinkage by stabilizing the polymer's crystalline structure", "Is only needed for cotton fabrics", "Replaces the need for dyeing"], correct: "Locks in the fabric's dimensional stability and reduces future shrinkage by stabilizing the polymer's crystalline structure", exp: "Heat-setting above the polymer's glass transition (but below melting) relaxes internal stresses and stabilizes the crystalline structure of thermoplastic fibers, locking in dimensions and preventing later shrinkage/distortion from heat exposure.", difficulty: "advanced", tags: ["heat-setting"] },
{ q: "If polyester fabric is heat-set at too LOW a temperature for the required dwell time, what problem is most likely to appear later?", options: ["The fabric becomes permanently too stiff", "The fabric can still shrink or distort (e.g., in garment washing/pressing) because the polymer wasn't fully stabilized", "The fabric loses all its color instantly", "Nothing — heat-setting temperature never matters"], correct: "The fabric can still shrink or distort (e.g., in garment washing/pressing) because the polymer wasn't fully stabilized", exp: "Insufficient heat-set temperature/time fails to fully stabilize the polymer's molecular structure, so the fabric retains latent shrinkage/distortion potential that shows up later during washing, steaming, or ironing.", difficulty: "advanced", tags: ["heat-setting","defects"] },

// ---- Chemical finishing ----
{ q: "A softener finish is applied to fabric mainly to improve:", options: ["Tensile strength", "Hand-feel/drape (softness) and sometimes sewability, though it can slightly reduce absorbency depending on type", "Colorfastness to light", "Flame resistance"], correct: "Hand-feel/drape (softness) and sometimes sewability, though it can slightly reduce absorbency depending on type", exp: "Softeners (cationic, silicone, or other types) coat fibers to reduce friction and improve hand-feel/drape; some types (especially heavy silicone/cationic softeners) can reduce moisture absorbency as a side effect, an important tradeoff for products needing high wicking.", difficulty: "basic", tags: ["softener"] },
{ q: "A durable water-repellent (DWR) finish makes fabric shed water while remaining breathable mainly by:", options: ["Completely sealing all pores in the fabric like a plastic laminate", "Lowering the fabric surface energy so water forms beads and rolls off, without blocking the fabric's air/vapor permeability", "Adding a rubber coating over the entire fabric", "Increasing the fabric's absorbency"], correct: "Lowering the fabric surface energy so water forms beads and rolls off, without blocking the fabric's air/vapor permeability", exp: "DWR finishes (often fluorocarbon or newer non-fluorinated chemistries) change the fiber surface's wettability so water beads up rather than soaking in, while the fabric structure itself remains open enough for air/moisture vapor to pass through — distinct from a fully waterproof laminate/coating.", difficulty: "advanced", tags: ["water-repellent"] },
{ q: "Flame-retardant (FR) finishing on cotton typically works by treating the fiber with chemicals that:", options: ["Make the fiber completely non-combustible under any condition permanently with a single wash-durable treatment always", "Alter the fiber's combustion/pyrolysis chemistry to promote char formation and self-extinguishing instead of sustained flaming", "Only add color, with flame resistance as a side effect", "Work by increasing the fabric's oxygen permeability"], correct: "Alter the fiber's combustion/pyrolysis chemistry to promote char formation and self-extinguishing instead of sustained flaming", exp: "FR finishes chemically interfere with cellulose's normal pyrolysis pathway, favoring char (carbon residue) formation over flammable volatile gas release, which slows or stops flame spread — durability of this effect varies by chemistry and wash cycles.", difficulty: "advanced", tags: ["flame-retardant"] },
{ q: "'Easy-care' or 'wrinkle-free' resin finishing on cotton (using cross-linking agents like DMDHEU) works by:", options: ["Coating the fabric surface with wax only", "Forming cross-links between cellulose polymer chains, which helps the fabric recover its shape after creasing instead of staying wrinkled", "Removing all the cellulose from the fiber", "Only affecting the fabric's color, not its wrinkle behavior"], correct: "Forming cross-links between cellulose polymer chains, which helps the fabric recover its shape after creasing instead of staying wrinkled", exp: "Cross-linking agents chemically bridge adjacent cellulose chains, restricting their ability to slide past each other when bent — this gives the fabric elastic 'memory' to spring back from creases, at some cost to tensile strength and tear strength.", difficulty: "advanced", tags: ["wrinkle-free","cross-linking"] },
{ q: "A common tradeoff/side effect of durable-press (wrinkle-free) resin finishing on cotton is:", options: ["Increased tensile and tear strength", "Reduced tensile strength, tear strength, and abrasion resistance due to the cross-linking restricting fiber flexibility", "Permanently brighter color with no other effect", "Complete elimination of any shrinkage forever with zero downside"], correct: "Reduced tensile strength, tear strength, and abrasion resistance due to the cross-linking restricting fiber flexibility", exp: "The same cross-linking that gives wrinkle recovery also makes the cellulose chains less able to flex and absorb stress, which is a well-known tradeoff reducing tensile/tear strength and abrasion resistance — finishers must balance wrinkle-recovery gain against this strength loss.", difficulty: "advanced", tags: ["wrinkle-free","tradeoffs"] },
{ q: "Enzyme washing (using cellulase enzymes) on denim garments is done to achieve:", options: ["A permanent stiff, board-like hand-feel", "A softer hand-feel and a faded, 'stone-washed' look by selectively degrading surface indigo-rich fibrils", "Adding new indigo color to the garment", "Increasing the garment's shrinkage resistance"], correct: "A softer hand-feel and a faded, 'stone-washed' look by selectively degrading surface indigo-rich fibrils", exp: "Cellulase enzymes selectively attack the loose, protruding surface fibrils of the cotton yarn (which carry most of the surface indigo, due to indigo's ring-dyeing nature), softening the fabric and abrading away color for a faded look, replacing or supplementing abrasive stone washing.", difficulty: "advanced", tags: ["enzyme-wash","biopolishing"] },
{ q: "'Biopolishing' with cellulase enzymes on cotton knitwear is primarily done to:", options: ["Add extra pilling to the fabric surface", "Remove protruding surface fibrils (fuzz), reducing pilling tendency and giving a smoother, cleaner fabric surface", "Increase the fabric's stiffness permanently", "Dye the fabric a lighter shade"], correct: "Remove protruding surface fibrils (fuzz), reducing pilling tendency and giving a smoother, cleaner fabric surface", exp: "Biopolishing uses cellulase enzymes to selectively hydrolyze and remove the short, loose fiber ends protruding from the yarn surface — since these loose fibrils are what tangle together to form pills, removing them reduces future pilling and gives a smoother hand-feel.", difficulty: "intermediate", tags: ["biopolishing"] },
{ q: "Antimicrobial finishes on textiles (e.g., using silver-based or quaternary ammonium compounds) are primarily intended to:", options: ["Change the fabric's color permanently", "Inhibit the growth of odor-causing bacteria and microbes on the fabric surface", "Increase fabric absorbency significantly", "Replace the need for any dyeing process"], correct: "Inhibit the growth of odor-causing bacteria and microbes on the fabric surface", exp: "Antimicrobial finishes target bacterial/microbial growth on the fiber surface (a major cause of odor in sportswear/activewear), not color or absorbency, and their effectiveness/durability depends heavily on the specific chemistry and wash durability.", difficulty: "basic", tags: ["antimicrobial-finish"] },
{ q: "A peach-finish (suede-like, ultra-soft surface) on microfiber fabric is typically achieved through:", options: ["Heavy starching only", "A combination of fine fiber (microfiber/split fiber) construction with mechanical abrasion (e.g., emery/sanding) to raise an extremely fine, short surface nap", "Bleaching alone", "Adding a thick pigment print coating"], correct: "A combination of fine fiber (microfiber/split fiber) construction with mechanical abrasion (e.g., emery/sanding) to raise an extremely fine, short surface nap", exp: "Peach finish depends on very fine denier fibers (so the raised nap is short and dense enough to feel like suede) combined with controlled mechanical abrasion (sanding/emerizing) that raises this ultra-fine surface texture.", difficulty: "advanced", tags: ["peach-finish","microfiber"] },

// ---- Colour science & testing ----
{ q: "In a spectrophotometer-based color matching system, 'metamerism' refers to the problem where:", options: ["Two fabric samples always look identical under every light source once matched", "Two colors that match under one light source (e.g., daylight) appear to be a different shade under another light source (e.g., store fluorescent light)", "A dye fades completely after one wash", "A fabric has no measurable color at all"], correct: "Two colors that match under one light source (e.g., daylight) appear to be a different shade under another light source (e.g., store fluorescent light)", exp: "Metamerism happens when two color recipes with different underlying spectral compositions happen to produce the same visual color under one specific light source, but diverge under a different spectral light source — a major QC headache in shade matching across dye lots or trims.", difficulty: "advanced", tags: ["metamerism"] },
{ q: "The CIELAB (L*a*b*) color space is widely used in textile shade matching because it:", options: ["Only measures fabric weight, not color", "Numerically expresses color in a way that closely correlates to human visual perception (lightness, red-green, yellow-blue), enabling objective Delta-E shade difference calculations", "Cannot be used for digital color communication", "Only works for white fabrics"], correct: "Numerically expresses color in a way that closely correlates to human visual perception (lightness, red-green, yellow-blue), enabling objective Delta-E shade difference calculations", exp: "CIELAB gives three numeric coordinates (L* lightness, a* red/green, b* yellow/blue) that map closely to perceived color, allowing a single 'Delta-E' number to objectively quantify how different two shades are — critical for pass/fail shade approval between lab dip and bulk production.", difficulty: "advanced", tags: ["CIELAB","delta-e"] },
{ q: "Colorfastness to crocking (rubbing) testing (e.g., AATCC 8 / ISO 105-X12) measures:", options: ["How much a fabric shrinks when washed", "How much color transfers from the fabric surface onto a white rubbing cloth under dry and wet rubbing conditions", "The fabric's resistance to sunlight fading", "The strength of the fabric's seams"], correct: "How much color transfers from the fabric surface onto a white rubbing cloth under dry and wet rubbing conditions", exp: "Crocking tests rub a standard white test cloth against the dyed fabric under controlled pressure (both dry and wet), then grade the color transferred using a grey scale — this predicts real-world color transfer onto skin or other garments during wear.", difficulty: "intermediate", tags: ["crocking","colorfastness"] },
{ q: "A fabric passes dry crocking (grade 4-5) but fails wet crocking (grade 2) badly. What does this most likely indicate about the dyeing process?", options: ["The fabric was never dyed at all", "Poor fixation and/or inadequate soaping-off, leaving loosely-bound/unfixed dye that only transfers when moisture is present", "The fabric's GSM is too high", "The test method itself is invalid"], correct: "Poor fixation and/or inadequate soaping-off, leaving loosely-bound/unfixed dye that only transfers when moisture is present", exp: "Wet crocking is far more sensitive to unfixed/surface dye than dry crocking because moisture helps dissolve and transfer loose dye molecules — a big dry-vs-wet gap points directly to insufficient fixation or wash-off after dyeing.", difficulty: "advanced", tags: ["crocking","fixation"] },
{ q: "The 'grey scale for staining' (used alongside colorfastness tests) is rated from Grade 1 to Grade 5, where:", options: ["Grade 1 means no staining/change at all (best) and Grade 5 means severe staining (worst)", "Grade 5 means no staining/change at all (best) and Grade 1 means severe staining (worst)", "The grades measure fabric weight, not color change", "Grades only apply to synthetic fibers"], correct: "Grade 5 means no staining/change at all (best) and Grade 1 means severe staining (worst)", exp: "On the standard grey scale, Grade 5 = no visible change/staining (excellent fastness) down to Grade 1 = severe change/staining (very poor fastness) — a common point of confusion since the numbering feels 'backwards' to newcomers.", difficulty: "intermediate", tags: ["grey-scale","colorfastness"] },
{ q: "Colorfastness to light testing (e.g., using a xenon-arc fading lamp, AATCC 16 / ISO 105-B02) is especially critical for which product category?", options: ["Undergarments only", "Outdoor/curtain fabrics, sportswear, and other products with prolonged sunlight exposure", "Fabrics that will never be exposed to any light", "Only white, undyed fabrics"], correct: "Outdoor/curtain fabrics, sportswear, and other products with prolonged sunlight exposure", exp: "Light fastness is tested by exposing dyed samples to a calibrated xenon-arc light source and comparing fading against a blue-wool reference scale — it matters most for products with heavy, prolonged light exposure like curtains, outdoor gear, and car interiors.", difficulty: "intermediate", tags: ["light-fastness"] },
{ q: "A buyer's lab report shows the shade Delta-E (CMC 2:1) between the bulk fabric and the approved lab dip is 1.8, against a tolerance limit of 1.0. This means:", options: ["The shade passes easily since 1.8 is a small number in absolute terms", "The shade FAILS — the measured color difference exceeds the buyer's approved tolerance, risking rejection", "Delta-E has no relation to shade approval", "The fabric's GSM is out of spec, unrelated to color"], correct: "The shade FAILS — the measured color difference exceeds the buyer's approved tolerance, risking rejection", exp: "Delta-E is the objective numeric shade difference; when it exceeds the buyer's specified tolerance (here 1.0), the bulk dyeing is considered an unacceptable shade deviation from the approved lab dip, regardless of how small the number looks in isolation.", difficulty: "advanced", tags: ["delta-e","QC"] },
{ q: "Sublimation fastness testing is specifically important for which dyeing/fiber combination?", options: ["Cotton dyed with reactive dye", "Polyester dyed with disperse dye, since disperse dyes can sublime (vaporize) under heat and transfer/stain during ironing or heat-transfer processes", "Wool dyed with acid dye", "Nylon dyed with basic dye"], correct: "Polyester dyed with disperse dye, since disperse dyes can sublime (vaporize) under heat and transfer/stain during ironing or heat-transfer processes", exp: "Disperse dyes have a molecular property allowing them to sublime (go from solid directly to vapor) under heat, which can cause color to migrate/stain adjacent white fabric during hot pressing/ironing or heat-transfer printing — a defect specific to this dye-fiber combination.", difficulty: "advanced", tags: ["sublimation-fastness"] },

// ---- Effluent / sustainability ----
{ q: "An Effluent Treatment Plant (ETP) at a dyeing mill primarily exists to:", options: ["Add color back into finished fabric", "Treat wastewater (removing dye, chemicals, and pollutants) before it is discharged, to meet environmental discharge standards", "Speed up the dyeing process itself", "Store finished fabric before shipment"], correct: "Treat wastewater (removing dye, chemicals, and pollutants) before it is discharged, to meet environmental discharge standards", exp: "Dyeing and wet processing generate wastewater loaded with unfixed dye, salts, and chemical auxiliaries; an ETP uses physical, chemical, and biological treatment stages to reduce pollutant load (COD/BOD/color) before the water is legally discharged or reused.", difficulty: "basic", tags: ["ETP","effluent"] },
{ q: "'COD' (Chemical Oxygen Demand) is a key parameter monitored in dye-house effluent because it measures:", options: ["The fabric's colorfastness rating", "The total amount of oxygen required to chemically oxidize the organic and inorganic pollutants in the wastewater — a proxy for overall pollution load", "The exact dye recipe used in a batch", "The fabric's final GSM after finishing"], correct: "The total amount of oxygen required to chemically oxidize the organic and inorganic pollutants in the wastewater — a proxy for overall pollution load", exp: "COD is a standard environmental metric: higher COD means more oxidizable pollutant load in the wastewater, so regulators set maximum allowable COD limits for treated effluent discharge, and mills must reduce it via the ETP.", difficulty: "advanced", tags: ["COD","effluent"] },
{ q: "Switching from conventional reactive dyeing to low-salt or salt-free reactive dyeing technology mainly helps sustainability by:", options: ["Increasing water use significantly", "Reducing the total dissolved solids (salt) load discharged in effluent, which is difficult and costly to remove in standard treatment", "Making all shades permanently darker", "Eliminating the need for any fixation step"], correct: "Reducing the total dissolved solids (salt) load discharged in effluent, which is difficult and costly to remove in standard treatment", exp: "Conventional reactive dyeing uses large amounts of salt to drive exhaustion; this salt largely ends up in the effluent as dissolved solids, which standard biological ETP treatment struggles to remove — low-salt dye technology directly reduces this specific pollution burden.", difficulty: "advanced", tags: ["sustainability","salt"] },
{ q: "Water recycling/reuse systems (e.g., reverse osmosis on ETP-treated water) in a dye house are adopted mainly to:", options: ["Add more dye chemicals to the process", "Reduce fresh water consumption and discharge volume by reusing treated water back into processes like rinsing or cooling", "Increase the fabric's final shade depth", "Replace the need for any dyeing chemicals"], correct: "Reduce fresh water consumption and discharge volume by reusing treated water back into processes like rinsing or cooling", exp: "Wet processing is extremely water-intensive; recycling treated water back into less-sensitive process steps (rinsing, cooling, boiler feed) cuts both fresh water withdrawal and the volume of new effluent generated, a major cost and sustainability lever.", difficulty: "intermediate", tags: ["water-recycling"] },
{ q: "'Azo dye' restrictions in textile regulations (e.g., REACH in the EU) specifically ban certain azo dyes because they can:", options: ["Fade too quickly in sunlight", "Break down (under reductive conditions, e.g., skin contact/perspiration) into carcinogenic aromatic amines", "Only work on wool, limiting their usefulness", "Cost more than other dye classes"], correct: "Break down (under reductive conditions, e.g., skin contact/perspiration) into carcinogenic aromatic amines", exp: "A specific list of azo dyes can cleave at the azo bond under reducing conditions (such as those found on skin) to release aromatic amines classified as carcinogenic — this health risk, not dyeing performance, is why these specific azo dyes are restricted/banned, not azo dyes in general.", difficulty: "advanced", tags: ["azo-dye-ban","compliance"] },
{ q: "OEKO-TEX Standard 100 certification for a finished textile product primarily verifies that:", options: ["The factory has a specific production capacity", "The product has been tested and found free of/below-limit for a defined list of harmful substances (e.g., certain dyes, formaldehyde, heavy metals)", "The fabric has a specific GSM range", "The garment was sewn using a particular machine brand"], correct: "The product has been tested and found free of/below-limit for a defined list of harmful substances (e.g., certain dyes, formaldehyde, heavy metals)", exp: "OEKO-TEX Standard 100 is a product-level (not factory-level) certification confirming lab testing against a defined list of regulated/harmful substances across dyes, finishing chemicals, and residues — it addresses consumer safety, not production capacity or process/social compliance (that's separate certifications).", difficulty: "intermediate", tags: ["OEKO-TEX","compliance"] },

// ---- Auxiliaries, process control, faults, extra finishing/testing ----
{ q: "A sequestering (chelating) agent is added to hard water before dyeing mainly to:", options: ["Add extra hardness to help exhaustion", "Bind calcium/magnesium ions so they don't precipitate with dye or form insoluble deposits that cause dull, uneven shades", "Permanently soften the fiber", "Replace the need for salt in reactive dyeing"], correct: "Bind calcium/magnesium ions so they don't precipitate with dye or form insoluble deposits that cause dull, uneven shades", exp: "Hard water's Ca2+/Mg2+ ions can react with certain dyes/soaps to form insoluble precipitates that deposit unevenly on fabric, causing dullness and specks; a sequestering agent binds these ions first, keeping the bath clean and giving level, bright shades.", difficulty: "advanced", tags: ["water-hardness","auxiliaries"] },
{ q: "An anti-foaming agent is used in jet/soft-flow dyeing machines primarily because excessive foam:", options: ["Improves dye penetration into the fabric", "Can cause uneven liquor circulation and localized dyeing defects, plus overflow/mechanical issues in high-turbulence machines", "Increases the machine's dyeing speed", "Has no real effect on dyeing quality"], correct: "Can cause uneven liquor circulation and localized dyeing defects, plus overflow/mechanical issues in high-turbulence machines", exp: "In high-agitation machines like jet dyeing, foam disrupts even liquor flow and contact with the fabric, risking patchy dyeing, and can physically overflow or interfere with liquor level sensors — anti-foam keeps circulation consistent.", difficulty: "advanced", tags: ["auxiliaries","jet-dyeing"] },
{ q: "Why is pH control critical throughout most dyeing processes (e.g., keeping reactive dyeing alkaline, acid dyeing acidic)?", options: ["pH has no effect on dye-fiber reactions", "Each dye class requires a specific pH range for correct dye-fiber bonding/reaction chemistry to occur efficiently; wrong pH gives poor exhaustion, fixation, or fastness", "pH only affects the fabric's final GSM", "pH control is only relevant for bleaching, not dyeing"], correct: "Each dye class requires a specific pH range for correct dye-fiber bonding/reaction chemistry to occur efficiently; wrong pH gives poor exhaustion, fixation, or fastness", exp: "Reactive dye fixation needs alkaline pH to activate the cellulose's reactive sites; acid dyeing needs acidic pH to protonate protein fiber amine groups — using the wrong pH for a given dye class directly causes poor exhaustion/fixation and fastness failures.", difficulty: "intermediate", tags: ["pH-control"] },
{ q: "A cationic fixing agent applied AFTER reactive or direct dyeing (a post-treatment) improves wet/wash fastness mainly by:", options: ["Adding new color to the fabric", "Forming a complex with the anionic dye molecules on the fiber, making them larger and less water-soluble/less easily washed out", "Removing all the dye and re-dyeing", "Bleaching the fabric white again"], correct: "Forming a complex with the anionic dye molecules on the fiber, making them larger and less water-soluble/less easily washed out", exp: "Cationic fixing agents are positively charged polymers that bind to the anionic (negatively charged) dye already on the fiber, forming a larger, less water-soluble complex that resists washing out — commonly used to boost wet fastness of direct and some reactive dyeings.", difficulty: "advanced", tags: ["fixing-agent"] },
{ q: "Silicone softeners are generally preferred over simple stearic-acid-based (fatty) softeners when the priority is:", options: ["The absolute lowest possible cost regardless of feel", "A very smooth, slick, long-lasting soft hand-feel with good lubricity, often at a higher cost", "Maximum water absorbency retention with zero softness benefit", "Adding stiffness rather than softness"], correct: "A very smooth, slick, long-lasting soft hand-feel with good lubricity, often at a higher cost", exp: "Silicone (especially amino-silicone) softeners give a superior, more durable slick/smooth hand-feel and lubricity compared to basic fatty-acid softeners, but at higher cost — the choice is a cost-vs-hand-feel tradeoff decision.", difficulty: "intermediate", tags: ["softener","comparison"] },
{ q: "Optical brightening agents (OBAs), used to make 'whites' look whiter-than-white, work by:", options: ["Bleaching out all remaining natural color completely", "Absorbing invisible UV light and re-emitting it as visible blue light, which counteracts the fabric's natural slight yellowness", "Adding a physical blue pigment coating", "Reducing the fabric's overall reflectance"], correct: "Absorbing invisible UV light and re-emitting it as visible blue light, which counteracts the fabric's natural slight yellowness", exp: "OBAs are fluorescent compounds that absorb invisible UV light and re-emit it in the visible blue spectrum; this added blue light optically offsets the faint natural yellow tint of bleached fiber, creating a 'whiter than white' visual effect rather than true chemical whitening.", difficulty: "advanced", tags: ["optical-brightener"] },
{ q: "'Tailing' is a common batch dyeing fault where:", options: ["The fabric is dyed perfectly even from start to end of the batch", "The color at the end (tail) of the fabric roll differs noticeably from the start (head), usually from dye exhausting unevenly over the run time", "The fabric shrinks only at one end", "The dye bath overflows"], correct: "The color at the end (tail) of the fabric roll differs noticeably from the start (head), usually from dye exhausting unevenly over the run time", exp: "Tailing occurs when dye concentration in the bath (or on a continuous range) changes as the run progresses — e.g., depleting faster than expected — leaving a visible shade gradient from the beginning to the end of the fabric roll.", difficulty: "advanced", tags: ["dyeing-faults","tailing"] },
{ q: "'Listing' (or 'selvedge/list' unevenness) is a dyeing defect specifically referring to:", options: ["Uneven color along the length of a roll", "A difference in shade or dye uptake specifically at the fabric edges (selvedges) compared to the main body of the fabric", "Missing yarns in the weave", "A print registration error"], correct: "A difference in shade or dye uptake specifically at the fabric edges (selvedges) compared to the main body of the fabric", exp: "Listing refers to shade variation concentrated at the fabric's selvedge/edges — often caused by different tension, folding, or liquor flow at the edges during processing compared to the fabric's center.", difficulty: "advanced", tags: ["dyeing-faults","listing"] },
{ q: "A 'lab dip' in the dyeing approval process refers to:", options: ["The final bulk production dyeing run", "A small-scale trial dyeing done in the lab to match a target shade before committing to full bulk production", "A test of the fabric's tensile strength", "A wash-testing procedure only"], correct: "A small-scale trial dyeing done in the lab to match a target shade before committing to full bulk production", exp: "Lab dips are small swatch trials used to fine-tune the dye recipe and get buyer shade approval before scaling up — this avoids wasting large volumes of fabric/dye if the recipe needs adjustment.", difficulty: "basic", tags: ["lab-dip"] },
{ q: "Why can a dye recipe that matches perfectly in a small lab-dip trial sometimes fail to reproduce the exact shade in bulk production?", options: ["Lab dips and bulk dyeing always give identical results with no exceptions", "Scale-up differences in liquor ratio, machine type, heating/dosing rate, and water quality can all shift dye exhaustion and final shade versus the lab-scale trial", "Bulk dyeing never uses the same dye class as the lab dip", "The fabric type always changes between lab and bulk"], correct: "Scale-up differences in liquor ratio, machine type, heating/dosing rate, and water quality can all shift dye exhaustion and final shade versus the lab-scale trial", exp: "Lab-to-bulk shade reproduction is a known technical challenge because process variables (liquor ratio, dosing speed, machine circulation, water hardness) rarely scale perfectly, so bulk dye recipes often need adjustment/correction from the original lab dip.", difficulty: "advanced", tags: ["lab-dip","scale-up"] },
{ q: "A UV-protection (UPF) finish on outdoor/sports fabric works mainly by:", options: ["Making the fabric completely opaque to visible light only", "Incorporating UV-absorbing compounds (or reflective particles like titanium dioxide) into/onto the fiber to block or absorb ultraviolet radiation before it passes through", "Increasing the fabric's water absorbency", "Adding a flame-retardant property as its main function"], correct: "Incorporating UV-absorbing compounds (or reflective particles like titanium dioxide) into/onto the fiber to block or absorb ultraviolet radiation before it passes through", exp: "UPF finishes work by chemically absorbing UV radiation (organic UV absorbers) or physically reflecting/scattering it (inorganic particles like TiO2/ZnO), reducing the amount of harmful UV that penetrates through to skin.", difficulty: "intermediate", tags: ["UV-finish"] },
{ q: "Anti-static finishes are particularly important for synthetic fibers like polyester and nylon because these fibers:", options: ["Naturally conduct electricity very well, requiring no finish", "Are hydrophobic and poor electrical conductors, so they readily build up static charge from friction, especially in low-humidity conditions", "Never experience friction during wear or processing", "Only need anti-static treatment when dyed dark colors"], correct: "Are hydrophobic and poor electrical conductors, so they readily build up static charge from friction, especially in low-humidity conditions", exp: "Because synthetic fibers absorb very little moisture, they lack the surface conductivity that helps natural fibers dissipate static charge, so friction (from wear, processing, or dry air) causes noticeable static buildup unless an anti-static finish (often adding surface conductivity/moisture affinity) is applied.", difficulty: "intermediate", tags: ["anti-static"] },
{ q: "Stiffening/starching finishes are applied to some fabrics (e.g., shirting, some export woven fabrics before shipment) mainly to:", options: ["Permanently reduce the fabric's flexibility forever with no way to reverse it", "Give the fabric a crisp, full hand-feel and better shape for cutting/sewing or display, often reversible with washing", "Add color to the fabric surface", "Increase the fabric's moisture absorbency"], correct: "Give the fabric a crisp, full hand-feel and better shape for cutting/sewing or display, often reversible with washing", exp: "Starch/stiffening finishes are typically temporary, wash-removable treatments applied to give body/crispness for better cutting, sewing precision, or retail presentation — unlike permanent resin cross-linking finishes.", difficulty: "basic", tags: ["stiffening-finish"] },
{ q: "Relaxation shrinkage testing (measuring how much fabric shrinks simply by soaking/washing with no mechanical action) is done separately from consolidation/progressive shrinkage testing because:", options: ["They always give identical results, so testing both is redundant", "Relaxation shrinkage reflects residual tension/stress release from fabric formation, while progressive shrinkage reflects cumulative felting/entanglement effects over repeated washes — different root causes need different fixes", "Neither type of shrinkage matters for finished garments", "Only synthetic fibers experience any kind of shrinkage"], correct: "Relaxation shrinkage reflects residual tension/stress release from fabric formation, while progressive shrinkage reflects cumulative felting/entanglement effects over repeated washes — different root causes need different fixes", exp: "Relaxation shrinkage happens once, as fibers/yarns relax internal stresses built up during spinning/weaving/finishing under tension; progressive (felting) shrinkage builds up gradually over many wash cycles from fiber entanglement — mills must control both mechanisms with different process solutions (e.g., sanforizing for relaxation, resin/finish for felting-prone wool).", difficulty: "advanced", tags: ["shrinkage-testing"] },
{ q: "Continuous dyeing ranges are generally chosen over batch/exhaust dyeing machines for which scenario?", options: ["Very small, highly varied fashion orders with frequent color changes", "Very large-volume, relatively few-color orders where high throughput and lower per-meter processing cost matter most", "Orders requiring extremely high liquor ratio for gentle handling", "Only for dyeing loose fiber stock, never fabric"], correct: "Very large-volume, relatively few-color orders where high throughput and lower per-meter processing cost matter most", exp: "Continuous ranges (like pad-steam) have high setup/changeover costs but very high throughput once running, making them economical for large, low-variety volume orders — whereas batch machines suit smaller, more frequently-changing color orders despite lower per-hour output.", difficulty: "intermediate", tags: ["continuous-vs-batch"] },
{ q: "During mercerization, cotton fiber strength typically increases by roughly how much when done correctly under tension, compared to untreated cotton?", options: ["No change in strength at all", "Approximately 20-30% increase in tensile strength", "A decrease of about 50%", "An increase of over 300%"], correct: "Approximately 20-30% increase in tensile strength", exp: "Mercerization under tension is well documented to increase cotton fiber tensile strength by roughly 20-30% due to the fiber's structural reorganization (increased crystallinity/orientation) during the caustic swelling and tension-set process, alongside the luster and dye-uptake gains.", difficulty: "advanced", tags: ["mercerization","strength"] },
{ q: "CIE Whiteness Index is used in quality control of bleached/optically brightened fabric mainly to:", options: ["Measure the fabric's exact GSM", "Give an objective numeric value for perceived 'whiteness,' allowing consistent comparison and pass/fail QC decisions between batches instead of relying on visual judgment alone", "Measure the strength of the fabric's seams", "Replace the need for any bleaching process"], correct: "Give an objective numeric value for perceived 'whiteness,' allowing consistent comparison and pass/fail QC decisions between batches instead of relying on visual judgment alone", exp: "Because 'whiteness' involves both brightness and a slight blue tint (from OBAs) that's hard to judge consistently by eye, the CIE Whiteness Index formula (derived from spectrophotometer L*a*b* or XYZ readings) gives a single objective number mills use for batch-to-batch QC consistency.", difficulty: "advanced", tags: ["whiteness-index"] },
{ q: "Which factor does NOT directly influence the rate of dye diffusion into a fiber during dyeing?", options: ["Dyeing temperature", "Fiber's internal molecular structure/crystallinity (accessibility of the polymer)", "Dye molecule size and its affinity for the fiber", "The brand name printed on the dye packaging"], correct: "The brand name printed on the dye packaging", exp: "Dye diffusion rate is governed by real physical/chemical factors — temperature (higher generally speeds diffusion), fiber accessibility/crystallinity, and the dye molecule's size/affinity — the packaging brand name has no bearing on the actual chemistry.", difficulty: "basic", tags: ["dye-diffusion"] },
{ q: "A dye house wants to reduce its carrier chemical usage in polyester disperse dyeing without lowering shade quality. The most technically sound solution is:", options: ["Dye at a lower temperature than before with no other change", "Switch to HTHP (high-temperature high-pressure) dyeing at around 130°C, which achieves adequate polymer chain mobility without needing a chemical carrier", "Add more salt to the bath instead", "Stop using disperse dye and switch to direct dye"], correct: "Switch to HTHP (high-temperature high-pressure) dyeing at around 130°C, which achieves adequate polymer chain mobility without needing a chemical carrier", exp: "Carriers were traditionally used to enable polyester dyeing at atmospheric-pressure boiling temperature (100°C) by swelling the fiber; HTHP dyeing instead reaches ~130°C directly (under pressure), giving sufficient polymer chain mobility for dye diffusion without needing carrier chemicals, which also reduces cost and environmental/odor concerns.", difficulty: "advanced", tags: ["disperse-dye","carrier","HTHP"] },
];
